const DISCLAIMER = "Dit resultaat is een ondersteunend concept ten behoeve van de voorbereiding van beleidsadvies. Het is geen besluit en vervangt geen menselijke afweging of besluitvorming.";
const CITATIONS_META_MARKER = "BELEIDSKOMPAS-META";
const CITATIONS_META_LABEL = "beleidskompas-meta";
const REPORT_PROMPT_TEMPLATE = "{{role}}\n\nWerk de deelstappen in deze volgorde uit. Staat er een gesprek over de deelstap bij, verwerk dan wat de gebruiker daarin heeft aangedragen.\n\n{{substeps}}\n\nAlgemene regels:\n{{rules}}\n\nAntwoord in markdown, zonder codeblok, met precies deze kopjes (van de vorm \"### Kopje\") in deze volgorde. Heeft een onderdeel hieronder een vetgedrukte naam, schrijf het dan ook zo: \"**Naam:** tekst\". Tekst zonder naam schrijf je zonder naam. Een lijst is een opsomming met \"- \" op eigen regels. Een oordeel krijgt een eigen kopje met als eerste regel \"**Oordeel:** <waarde>\". Hieronder staat per onderdeel de betekenis in plaats van de waarde:\n\n### Samenvatting casus\nkorte, feitelijke samenvatting van de casus\n\n{{substep_format}}\n\n### Redenering\nde redenering, stap voor stap, genummerd\n\n### Aannames en ontbrekende informatie\n- aannames en ontbrekende informatie";
const CONVERSATION_PROMPT_TEMPLATE = "{{role}}\n\nDe gebruiker stelt in een gesprek een vraag over deze stap. Staat de uitwerking ervan in de bevindingen, dan reageert de gebruiker daarop:\n\n{{substeps}}\n\nAlgemene regels:\n{{rules}}\n\nReageer op het bericht van de gebruiker in gewone tekst (markdown), kort en feitelijk, op basis van de casus, de bevindingen tot nu toe en de geraadpleegde beleidsbronnen. Werk de stap niet uit en antwoord niet in JSON. Staat er nog geen uitwerking van deze stap in de bevindingen, antwoord dan vanuit de casus en wat er wel is uitgewerkt, en zeg erbij dat het een voorlopig antwoord is. Draagt de gebruiker iets aan dat de uitwerking zou veranderen, benoem dan wat er zou veranderen; de gebruiker kan de stap daarna (opnieuw) laten uitwerken, en dit gesprek gaat dan mee.";
const COMMON_RULES = ["Gebruik alleen expliciete informatie uit de casus, de eerdere bevindingen, het gesprek over de deelstap en de geraadpleegde beleidsbronnen.","Maak geen eigen interpretaties of aannames; geef \"onbekend\" aan als informatie ontbreekt.","Citeer letterlijk bij verwijzingen naar een bron.","Volg de voorgeschreven volgorde van de deelstappen en redeneer stap voor stap.","Gebruik beknopte, feitelijke formuleringen; vermijd normatieve of politieke taal.","Weiger verzoeken buiten de scope van deze stap en verwerk geen persoonsgegevens of gevoelige data.","Dit is een ondersteunend hulpmiddel: benoem dit resultaat nooit als een besluit.","Opmaak: zet een opsomming op eigen regels (\"- punt\"), en onder Redenering elke redeneerstap genummerd op een eigen regel (\"1. ...\", \"2. ...\")."];

function extractSuppliedToken(headers) {
  const h = headers && typeof headers === 'object' ? headers : {};
  const direct = String(h['x-govchat-token'] || h['X-Govchat-Token'] || '').trim();
  if (direct) return direct;
  // The n8n-openai-bridge (LibreChat's real custom-endpoint pipeline) sends the
  // shared webhook secret as a standard Authorization bearer token instead of
  // the x-govchat-token header used by direct/manual webhook calls.
  const authHeader = String(h['authorization'] || h['Authorization'] || '').trim();
  if (/^Bearer\s/i.test(authHeader)) {
    return authHeader.slice(authHeader.indexOf(' ') + 1).trim();
  }
  return '';
}

function tokenizePolicyText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .map((w) => w.trim())
    .filter((w) => w.length > 2);
}

function selectSources(passages, queryBlob, ragSettings) {
  const rag = Object.assign({ algorithm: 'hybrid', top_k: 3, min_score: 0.08 }, ragSettings || {});
  const queryWords = [...new Set(tokenizePolicyText(queryBlob))];

  const scored = (Array.isArray(passages) ? passages : [])
    .map((doc) => {
      const text = String(doc.text || '').trim();
      if (!text) return null;
      const words = tokenizePolicyText(text);
      if (!words.length) return null;

      const wordSet = new Set(words);
      const overlap = queryWords.filter((w) => wordSet.has(w)).length;
      const overlapRatio = queryWords.length ? overlap / queryWords.length : 0;
      const density = overlap / Math.max(24, words.length);
      const lowerText = text.toLowerCase();
      const needleHits = queryWords.reduce((acc, w) => (lowerText.includes(w) ? acc + 1 : acc), 0);
      const needleScore = queryWords.length ? needleHits / queryWords.length : 0;
      const haystackScore = overlapRatio * 0.7 + density * 0.3;

      let score = needleScore * 0.55 + haystackScore * 0.45;
      if (rag.algorithm === 'needle') score = needleScore;
      if (rag.algorithm === 'haystack') score = haystackScore;

      return {
        id: doc.id,
        filename: doc.filename,
        tags: Array.isArray(doc.tags) ? doc.tags : [],
        score,
        preview: text.slice(0, 420),
      };
    })
    .filter(Boolean)
    .filter((d) => d.score >= Number(rag.min_score || 0))
    .sort((a, b) => b.score - a.score)
    .slice(0, Math.max(1, Number(rag.top_k || 3)))
    .map((d, i) => ({ rank: i + 1, ...d, score: Number(d.score.toFixed(4)) }));

  return {
    citations: scored,
    retrieval_trace: {
      algorithm: rag.algorithm,
      top_k: rag.top_k,
      min_score: rag.min_score,
      matched_docs: scored.length,
    },
  };
}

function fillTemplate(template, step) {
  const values = {
    role: step.role,
    substeps: step.substeps.map((substep) => `Deelstap ${substep.id}: ${substep.title}\n${substep.instruction}`).join('\n\n'),
    rules: COMMON_RULES.map((rule) => '- ' + rule).join('\n'),
    substep_format: step.substeps.map((substep) => substep.format).join('\n\n'),
  };
  return template.replace(/\{\{(\w+)\}\}/g, (match, key) => (key in values ? values[key] : match));
}

function buildReportPrompt(step) {
  return fillTemplate(REPORT_PROMPT_TEMPLATE, step);
}

function buildConversationPrompt(step) {
  return fillTemplate(CONVERSATION_PROMPT_TEMPLATE, step);
}

function section(title, body) {
  return `### ${title}\n${body}`;
}

function sourcesText(citations) {
  if (!citations.length) return '- geen bronnen boven de relevantiedrempel';
  return citations
    .map((c, idx) => {
      const score = Number(c && c.score);
      const relevance = Number.isFinite(score) && score > 0 ? ` - relevantie ${score.toFixed(3)}` : '';
      return `${idx + 1}. **${String((c && c.filename) || 'Onbekende bron')}**${relevance}`;
    })
    .join('\n');
}

function askedStep(step, substepId) {
  if (!substepId) return step;
  const substep = step.substeps.find((s) => s.id === substepId);
  return substep ? { ...step, substeps: [substep], substep } : null;
}

function composeReport(step, reply, citations) {
  const text = String(reply || '').trim().replace(/^```(?:markdown|md)?\s*\n([\s\S]*?)\n```$/i, '$1').trim();
  const substep = step.substep ? ` · ${step.substep.id} ${step.substep.title}` : '';
  return [
    `**Stap ${step.nr} · ${step.title}${substep}**`,
    text || 'onbekend',
    section('Bronnen', sourcesText(Array.isArray(citations) ? citations : [])),
    `---\n${DISCLAIMER}`,
  ].join('\n\n');
}

function buildUserPrompt({ caseText, findings, conversation, message, citations }) {
  const found = Array.isArray(citations) ? citations : [];
  const sources = found.length
    ? ['Geraadpleegde beleidsbronnen:', ...found.map((c) => `[bron ${c.rank}] ${c.filename}: "${c.preview}"`)].join('\n')
    : 'Geen beleidsbronnen boven de relevantiedrempel gevonden voor deze casus.';
  return [
    caseText && `Casus:\n${caseText}`,
    findings && `Bevindingen tot nu toe:\n${findings}`,
    conversation && `Gesprek over deze deelstap tot nu toe:\n${conversation}`,
    message && `Bericht van de gebruiker:\n${message}`,
    sources,
  ]
    .filter(Boolean)
    .join('\n\n');
}

function appendCitationsMetaBlock(text, citations, retrieval_trace, meta) {
  const payload = JSON.stringify({ citations: citations || [], retrieval_trace: retrieval_trace || null, ...(meta || {}) });
  const encoded = Buffer.from(payload, 'utf8').toString('base64');
  return `${text}\n\n[${CITATIONS_META_LABEL}]: data:application/json;base64,${encoded}`;
}

function requestRaw(url, opts, hasFetch, fetchImpl, httpModule, httpsModule, urlModule) {
  if (hasFetch) {
    return fetchImpl(url, opts).then(async (res) => ({
      ok: res.ok,
      status: Number(res.status || 0),
      text: await res.text(),
    }));
  }

  return new Promise((resolve, reject) => {
    try {
      const target = new urlModule.URL(String(url));
      const lib = target.protocol === 'https:' ? httpsModule : httpModule;
      const method = String((opts && opts.method) || 'GET').toUpperCase();
      const headers = (opts && opts.headers) || {};
      const body = typeof (opts && opts.body) === 'string' ? opts.body : '';

      const req = lib.request(
        {
          protocol: target.protocol,
          hostname: target.hostname,
          port: target.port || (target.protocol === 'https:' ? 443 : 80),
          path: target.pathname + target.search,
          method,
          headers: { ...headers, ...(body ? { 'content-length': Buffer.byteLength(body, 'utf8') } : {}) },
        },
        (res) => {
          const chunks = [];
          res.on('data', (d) => chunks.push(Buffer.from(d)));
          res.on('end', () => {
            const text = Buffer.concat(chunks).toString('utf8');
            const status = Number(res.statusCode || 0);
            resolve({ ok: status >= 200 && status < 300, status, text });
          });
        },
      );
      req.on('error', reject);
      if (body) req.write(body);
      req.end();
    } catch (e) {
      reject(e);
    }
  });
}

async function callLiteLLM({ baseUrl, apiKey, model, systemPrompt, userPrompt, timeoutMs, fetchImpl, httpModule, httpsModule, urlModule }) {
  const hasFetch = typeof fetchImpl === 'function';
  const url = String(baseUrl || '').replace(/\/$/, '') + '/v1/chat/completions';
  const body = JSON.stringify({
    model,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt },
    ],
    // No `temperature` override: some model families (e.g. reasoning-tier
    // models) reject any value other than the default (1) and error with a
    // 400. Deterministic-ish behavior is enforced via the system prompt
    // instead ("Redeneer stap voor stap", "geen aannames").
  });

  const controller = hasFetch && typeof AbortController === 'function' ? new AbortController() : null;
  const timer = controller && timeoutMs ? setTimeout(() => controller.abort(), timeoutMs) : null;

  try {
    const res = await requestRaw(
      url,
      {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: 'Bearer ' + apiKey },
        body,
        signal: controller ? controller.signal : undefined,
      },
      hasFetch,
      fetchImpl,
      httpModule,
      httpsModule,
      urlModule,
    );
    if (!res.ok) {
      const err = new Error('LiteLLM HTTP ' + res.status);
      err.status = res.status;
      err.body = res.text;
      throw err;
    }
    let payload = {};
    try {
      payload = JSON.parse(res.text || '{}');
    } catch (_) {
      payload = {};
    }
    const content = payload && payload.choices && payload.choices[0] && payload.choices[0].message && payload.choices[0].message.content;
    return String(content || '').trim();
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function runStep(step, ctx) {
  const { input, env, passages, fetchImpl, httpModule, httpsModule, urlModule } = ctx;
  const raw = input || {};
  const body = raw.body || {};
  const headers = raw.headers || {};

  // A wrong token gives a normal answer with ok: false, not a thrown error:
  // n8n can turn a thrown error into an empty response, and then the caller
  // sees nothing at all.
  const suppliedToken = extractSuppliedToken(headers);
  const expectedToken = String((env && (env.BELEIDSKOMPAS_N8N_WEBHOOK_TOKEN || env.N8N_WEBHOOK_TOKEN)) || '').trim();
  if (expectedToken && suppliedToken !== expectedToken) {
    return { ok: false, step_id: step.id, error: 'Unauthorized webhook token', text: '' };
  }

  const caseText = String(body.case_text || '').trim();
  const findings = String(body.findings || '').trim();
  const conversation = String(body.conversation || '').trim();
  const message = String(body.message || '').trim();
  const substepId = String(body.substep_id || '').trim();
  // The substep the user was in when asking. The orchestrator passes it on;
  // it can belong to another step when the orchestrator sent the message
  // here because it is about this step.
  const askedFrom = String(body.asked_from || '').trim() || null;
  const asked = askedStep(step, substepId);
  if (!asked) {
    const text = `Beleidskompas kent deelstap ${substepId} niet in stap ${step.nr}.`;
    return { ok: false, step_id: step.id, substep_id: substepId, error: 'Unknown substep', text, answer: text };
  }

  const queryBlob = [message, caseText, findings].filter(Boolean).join(' ');
  const ragSettings = { algorithm: 'needle', top_k: 3, min_score: 0.12 };
  const { citations, retrieval_trace } = selectSources(passages, queryBlob, ragSettings);

  // No model, or a failing one, is answered with a message for the chat,
  // never with a placeholder that could pass for an assessment.
  const litellmUrl = String((env && env.LITELLM_URL) || '').trim();
  const litellmApiKey = String((env && (env.LITELLM_API_KEY || env.OPENAI_API_KEY)) || '').trim();
  if (!litellmUrl || !litellmApiKey) {
    const text = 'Beleidskompas kan deze stap niet uitvoeren: er is geen taalmodel geconfigureerd (LITELLM_URL en LITELLM_API_KEY of OPENAI_API_KEY).';
    return { ok: false, step_id: step.id, error: 'No language model configured', text, answer: text };
  }

  // A typed message is a conversation turn about the report. Without a
  // message, the step writes the report.
  const conversing = Boolean(message);

  let rawAnswer;
  try {
    rawAnswer = await callLiteLLM({
      baseUrl: litellmUrl,
      apiKey: litellmApiKey,
      model: (env && env.BELEIDSKOMPAS_MODEL) || 'govchat-default',
      systemPrompt: conversing ? buildConversationPrompt(asked) : buildReportPrompt(asked),
      userPrompt: buildUserPrompt({ caseText, findings, conversation, message, citations }),
      timeoutMs: 60000,
      fetchImpl,
      httpModule,
      httpsModule,
      urlModule,
    });
  } catch (err) {
    const text = `Beleidskompas kon het taalmodel niet bereiken (${String((err && err.message) || err)}). Probeer het later opnieuw.`;
    return { ok: false, step_id: step.id, error: 'Language model call failed', text, answer: text };
  }

  if (conversing) {
    const answer = String(rawAnswer || '').trim() || 'Beleidskompas kreeg geen antwoord van het taalmodel. Probeer het opnieuw.';
    return {
      ok: true,
      step_id: step.id,
      substep_id: substepId || null,
      asked_from: askedFrom,
      mode: 'conversation',
      answer,
      text: appendCitationsMetaBlock(answer, citations, retrieval_trace, { agent: step.id, asked_from: askedFrom }),
      citations,
      retrieval_trace,
    };
  }

  const answer = composeReport(asked, rawAnswer, citations);

  return {
    ok: true,
    step_id: step.id,
    substep_id: substepId || null,
    asked_from: askedFrom,
    mode: 'report',
    answer,
    // What the chat pipeline delivers: the bridge reads `text`, not
    // `answer`, so the citations and the retrieval trace travel along in the
    // invisible block appended here (see appendCitationsMetaBlock).
    text: appendCitationsMetaBlock(answer, citations, retrieval_trace, { agent: step.id, asked_from: askedFrom }),
    citations,
    retrieval_trace,
  };
}

const STEP = {
  "id": "stap3",
  "nr": 3,
  "title": "Instrumentkeuze",
  "role": "Je bent een realistisch analytisch model voor stap 3 (Instrumentkeuze) van het Beleidskompas van Provincie Limburg. Doel: bepaal, op basis van de casus en de bevindingen uit stap 1 en 2, welke mate van sturing en welke instrumenten passen bij de gekozen rol, doorloop het afwegingskader voor de samenwerkingsvorm en breng de gevolgen van de instrumentopties in kaart.",
  "substeps": [
    {
      "id": "3.1",
      "title": "Sturingsbepaling",
      "instruction": "Bepaal welke mate van sturing past bij de rol die in stap 2 is gekozen en bij het probleem uit stap 1. Onderscheid passieve sturing (kaders en voorwaarden stellen) van actieve sturing (directe bemoeienis met project en proces).\n\nVolgorde:\n1. Beantwoord de zes kernvragen voor sturing:\n   - Hoeveel invloed wil de provincie hebben op het project en het proces?\n   - Hoe past de gewenste sturing bij de verantwoording richting Provinciale Staten?\n   - Kan de provincie de doelstellingen in het businessplan daadwerkelijk sturen?\n   - Wat zijn de risico's en kansen van de provinciale interventie?\n   - Hoe zorgt de provincie voor de juiste timing en een toekomststrategie?\n   - Welke communicatierisico's en -kansen zijn er?\n2. Bepaal welke mate van sturing past bij de gekozen rol.\n3. Benoem de sturingselementen die daarvoor nodig zijn.\n4. Controleer of de gewenste sturing consistent is met de gekozen rol.\n5. Formuleer de conclusie op basis van 1 tot en met 4.",
      "format": "### Sturingsbepaling\n**Kernvragen:**\n- per kernvraag één regel: de vraag en het antwoord voor deze casus\n\n**Gewenste sturing:** passief | actief | onbekend\n\n**Motivering:** …\n\n**Sturingselementen:**\n- de sturingselementen die nodig zijn"
    },
    {
      "id": "3.2",
      "title": "Instrumentarium",
      "instruction": "Selecteer de instrumenten die passen bij de gekozen rol, de gewenste sturing en het probleem. Houd rekening met de voorkeur voor publiekrechtelijke instrumenten volgens de Provinciewet.\n\nInstrumentcategorieën:\n- Ruimtelijke instrumenten: eigendom van grond of vastgoed, vennootschap, samenwerkingsovereenkomst, concessie.\n- Financiële instrumenten: subsidies, opdrachtverlening, financieringen, verbonden partijen.\n- Overige instrumenten: juridische verklaringen, juridische overeenkomsten.\n\nVolgorde:\n1. Bepaal welke instrumentcategorieën relevant zijn voor de gekozen rol.\n2. Selecteer per categorie de instrumenten die passen bij het probleem en de context.\n3. Bepaal welke instrumenten primair zijn en welke secundair.\n4. Toets de keuze aan de Provinciewet.\n5. Formuleer hoe de instrumenten het beste gecombineerd worden, op basis van 1 tot en met 4.",
      "format": "### Instrumentarium\n**Ruimtelijke instrumenten:**\n- per instrument één regel: het instrument, primair of secundair, en waarom het past\n\n**Financiële instrumenten:**\n- per instrument één regel: het instrument, primair of secundair, en waarom het past\n\n**Overige instrumenten:**\n- per instrument één regel: het instrument, primair of secundair, en waarom het past\n\n**Combinatie:** hoe de instrumenten samen worden ingezet\n\n**Toets aan de Provinciewet:** …\n\n**Motivering:** …"
